def _лінійно(x, вузли):
    """Кусково-лінійне відображення кута `x` за вузлами [(від, до)] по колу 0–360°:
    `від` зростає, останній відрізок замикається на перший через 360°."""
    x = x % 360.0
    for (x0, y0), (x1, y1) in zip(вузли, вузли[1:] + ((вузли[0][0] + 360.0, вузли[0][1] + 360.0),)):
        xx = x if x >= x0 else x + 360.0
        if x0 <= xx <= x1:
            return (y0 + (xx - x0) * (y1 - y0) / (x1 - x0)) % 360.0
    raise ValueError("кут %r поза вузлами кола" % (x,))

def у_коло_художника(h):
    """Кут тону CIELAB `h` → кут на колі художника (R 0°, G 180°)."""
    return _лінійно(h, _КОЛО)

def з_кола_художника(a):
    """Кут на колі художника → кут тону CIELAB (обернене до `у_коло_художника`)."""
    вузли = sorted((y, x) for x, y in _КОЛО)
    return round(_лінійно(a, tuple(вузли)), 1)

def зсув_на_колі(h, кут):
    """Тон CIELAB, що стоїть на `кут` градусів від `h` на колі художника (знак — напрям)."""
    return з_кола_художника(у_коло_художника(h) + float(кут))

def доповнення(h):
    """Друга сторона комплементу для тону CIELAB `h`: +180° на колі художника, назад у
    CIELAB. Єдине місце, де код будує протилежну сторону (схеми, спектри рис, палітра)."""
    return зсув_на_колі(h, 180.0)

def тепло(h):
    """Теплота тону CIELAB `h`, −1…1: b*/C* = sin h — жовтий (h 90°) найтепліший, синій (270°) найхолодніший,
    червоний і ціан (0°/180°) — межа. None — тону нема (теплота не виміряна, не нуль)."""
    return None if h is None else math.sin(math.radians(h))

def центри_відношення(h, rel):
    """Центри дуг відношення `rel` (з `RELATIONS`) від тону `h`: кожен зсув — на колі
    художника (`зсув_на_колі`), комплемент — `доповнення`; нульовий зсув — сам `h`."""
    off = RELATIONS[rel][0]
    if off == 180:
        return [доповнення(h)]
    if not off:
        return [h % 360]
    return [зсув_на_колі(h, off), зсув_на_колі(h, -off)]

def дуга_кола(h, пів):
    """Дуга тону CIELAB (від, до) — образ дуги кола художника з центром у тоні CIELAB `h` і пів-шириною
    `пів`° кола (КОЛІР-СХЕМИ, п.18). Ширина дуги — на колі, як і її зсув (`зсув_на_колі`): ±15°
    кола — той самий сектор у будь-якому тоні, а ±15° CIELAB — це ±7° кола в синіх і до ±38° у бурих. Силу
    членства в такій дузі судить `колір_відношення.сила_в_дузі`. Споживач — сім'я очей
    (`palettes.дуга_очей`) і ролі схем (`palettes.дуга`, 2.14-Б); спектри рис лишились кутами CIELAB."""
    return (з_кола_художника(у_коло_художника(h) - float(пів)) % 360.0,
            з_кола_художника(у_коло_художника(h) + float(пів)) % 360.0)

def arc(c,half):
    """Дуга (c − half, c + half) по модулю 360."""
    return ((c-half)%360, (c+half)%360)

def in_arc(h,a):
    """Чи кут h лежить у дузі a, з переходом через 0°."""
    lo,hi=a; return (lo<=h<=hi) if lo<=hi else (h>=lo or h<=hi)


# ═══ ЛІЧБА КОЛА: КУТ І ДУГА ═══
# Кут — градуси на будь-якому колі тону: тон CIELAB чи координата кола художника. На якому колі лічити, обирає
# читач (середина дуги CIELAB і середина її образу на колі художника — різні тони). Дуга (від, до) іде за ходом —
# проти годинникової стрілки, від `від` до `до` — і замкнена з обох країв, як `in_arc`. (x, x) — одна точка x
# (ширина 0), усе коло — `ПОВНЕ_КОЛО` (ширина 360; `in_arc` приймає його на всьому [0, 360]). Читачі тримали
# (x, x) то точкою, то всім колом (`… or 360`, «(x, x) — усе коло»), дошка 11298. Кути й кінці дуг, які
# повертають функції нижче, лежать у [0, 360); виняток — `ПОВНЕ_КОЛО`.
ПОВНЕ_КОЛО = (0.0, 360.0)

def нормувати(кут):
    """Кут у [0, 360). Від'ємне −ε після `% 360` дає 360.0, тож межу закрито явно."""
    к = float(кут) % 360.0
    return 0.0 if к >= 360.0 else к

def різниця_на_колі(a, b):
    """a − b коротшим шляхом по колу, [−180, 180): знак — напрям від b до a (+ — за ходом); протилежні — −180."""
    return нормувати(float(a) - float(b) + 180.0) - 180.0

def відстань_тонів(a, b):
    """Кут між a і b коротшим шляхом, [0, 180]; симетрична: |a − b| однаковий в обидва боки."""
    d = abs(float(a) - float(b)) % 360.0
    return min(d, 360.0 - d)

def зсув_за_ходом(від, кут):
    """Скільки градусів від `від` до `кут` за ходом, [0, 360): зсув кута від початку дуги."""
    return нормувати(float(кут) - float(від))

def ширина_дуги(дуга):
    """Довжина дуги (від, до) за ходом, 0…360: (x, x) — 0; `ПОВНЕ_КОЛО`, як і будь-яка дуга з до − від ≥ 360, — 360."""
    від, до = float(дуга[0]), float(дуга[1])
    return 360.0 if до - від >= 360.0 else зсув_за_ходом(від, до)

def _дуга(від, ширина):
    """Дуга з початку й ширини: ширина ≥ 360 — `ПОВНЕ_КОЛО`, ≤ 0 — точка `від`."""
    if ширина >= 360.0:
        return ПОВНЕ_КОЛО
    від = нормувати(від)
    return (від, нормувати(від + max(float(ширина), 0.0)))

def в_дузі_пів(h, дуга):
    """Чи h на напіввідкритій дузі [від, до): без верхнього краю, щоб сусідні дуги ділили межу, а не перетиналися.
    (x, x) — порожня, `ПОВНЕ_КОЛО` — усе [0, 360). Кути — у [0, 360), як для `in_arc`."""
    lo, hi = дуга
    return (lo <= h < hi) if lo <= hi else (h >= lo or h < hi)

def точка_дуги(дуга, частка):
    """Кут на дузі на `частка` її ширини від `від` за ходом: 0 — початок, 0.5 — середина, 1 — кінець."""
    return нормувати(float(дуга[0]) + float(частка) * ширина_дуги(дуга))

def середина_дуги(дуга):
    """Середина дуги за ходом — на тому колі, на якому дано дугу (`точка_дуги` з часткою 0.5)."""
    return точка_дуги(дуга, 0.5)

def тони_дуги(дуга, крок=1.0):
    """Кути дуги від `від` кроком `крок` за ходом, кінець — коли крок у нього влучає; на `ПОВНЕ_КОЛО` початок не
    повторюється."""
    крок = float(крок)
    if крок <= 0.0:
        raise ValueError("крок дуги має бути додатним")
    ш = ширина_дуги(дуга)
    n = math.ceil(ш / крок) if ш >= 360.0 else math.floor(ш / крок) + 1
    return [нормувати(float(дуга[0]) + k * крок) for k in range(n)]

def градуси_дуги(дуга):
    """Множина цілих градусів g, чий відрізок [g, g + 1) зачіпає дугу: від ⌊від⌋ до градуса кінця за ходом.
    (x, x) — один градус, `ПОВНЕ_КОЛО` і дуга, обидва кінці якої в одному градусі через усе коло, — усі 360."""
    від = float(дуга[0])
    перший = math.floor(від)
    кроків = min(math.floor(від - перший + ширина_дуги(дуга)), 359)
    return {(перший + k) % 360 for k in range(кроків + 1)}

def дуга_в_дузі(внутрішня, зовнішня):
    """Чи дуга `внутрішня` вся лежить у дузі `зовнішня`: обидва її кінці в зовнішній і кінець не раніше за початок
    (зсуви від початку зовнішньої). Кінці порівнюються самі, без суми зсуву й ширини, тож спільний кінець — усередині."""
    ш = ширина_дуги(зовнішня)
    if ш >= 360.0:
        return True
    if ширина_дуги(внутрішня) >= 360.0:
        return False
    з0, з1 = зсув_за_ходом(зовнішня[0], внутрішня[0]), зсув_за_ходом(зовнішня[0], внутрішня[1])
    return з0 <= з1 <= ш

def розширити_дугу(дуга, допуск):
    """Дуга, ширша на `допуск`° з кожного боку (від'ємний — вужча до середини); ширина ≥ 360 — `ПОВНЕ_КОЛО`."""
    ш = ширина_дуги(дуга)
    if ш >= 360.0:
        return ПОВНЕ_КОЛО
    нова = ш + 2.0 * float(допуск)
    if нова <= 0.0:
        с = середина_дуги(дуга)
        return (с, с)
    return _дуга(float(дуга[0]) - float(допуск), нова)

def перетин_дуг(a, b):
    """Спільні шматки двох замкнених дуг — список дуг, найширша першою (рівні — від меншого кута початку);
    [] — спільної точки нема. Шматків буває два (кожна дуга покриває обидва кінці іншої); дотик краями — точка.
    Кінці шматків — ті самі числа, що й кінці дуг (після `нормувати`)."""
    wa, wb = ширина_дуги(a), ширина_дуги(b)
    if wa >= 360.0:
        return [ПОВНЕ_КОЛО if wb >= 360.0 else _дуга(b[0], wb)]
    if wb >= 360.0:
        return [_дуга(a[0], wa)]
    s = зсув_за_ходом(a[0], b[0])
    шматки = []
    for п, к in ((s, s + wb), (s - 360.0, s + wb - 360.0)):   # b і її образ на оберт раніше: дотик через a[0]
        lo, hi = max(п, 0.0), min(к, wa)
        if lo <= hi:
            від = нормувати(b[0] if п > 0.0 else a[0])
            шматок = (lo, hi, від, від if lo == hi else нормувати(b[1] if к < wa else a[1]))
            if шматок not in шматки:
                шматки.append(шматок)
    шматки.sort(key=lambda ш: (-(ш[1] - ш[0]), ш[2]))
    return [(ш[2], ш[3]) for ш in шматки]

def об_єднати_дуги(a, b):
    """Найвужча дуга, що тримає обидві: коло без найширшої щілини між ними; щілини нема — `ПОВНЕ_КОЛО`. Із двох
    однаково широких щілин виключається та, що починається з меншого кута: відповідь не залежить від порядку дуг.
    Кінці — ті самі числа, що й кінці дуг (після `нормувати`)."""
    wa, wb = ширина_дуги(a), ширина_дуги(b)
    if wa >= 360.0 or wb >= 360.0:
        return ПОВНЕ_КОЛО
    s = зсув_за_ходом(a[0], b[0])
    a0, a1, b0, b1 = (нормувати(x) for x in (a[0], a[1], b[0], b[1]))
    відрізки = [(0.0, wa, a0, a1)]   # зсув від a[0]: (початок, кінець, кут початку, кут кінця)
    відрізки += [(s, s + wb, b0, b1)] if s + wb <= 360.0 else [(s, 360.0, b0, a0), (0.0, s + wb - 360.0, a0, b1)]
    відрізки.sort()
    злиті = [list(відрізки[0])]
    for п, к, кп, кк in відрізки[1:]:
        if п <= злиті[-1][1]:
            if к > злиті[-1][1]:
                злиті[-1][1], злиті[-1][3] = к, кк
        else:
            злиті.append([п, к, кп, кк])
    щілини = [(злиті[i][1], злиті[i + 1][0], злиті[i][3], злиті[i + 1][2]) for i in range(len(злиті) - 1)]
    щілини.append((злиті[-1][1], злиті[0][0] + 360.0, злиті[-1][3], злиті[0][2]))
    п, к, кп, кк = min(щілини, key=lambda щ: (-(щ[1] - щ[0]), щ[2]))
    if к - п <= 0.0:
        return ПОВНЕ_КОЛО
    return (кк, кп)

# ═══ СІМ'Ї КОЛЬОРУ: ОДНЕ ВИЗНАЧЕННЯ ДЛЯ РЕЧІ, ПАЛІТРИ Й РИСИ ═══
# Сім'я — область у Lab: об'єднання клітинок ISCC–NBS її блоків (таблиця `колір_сім_ї_вікна.md`),
# перенесене з Munsell H/V/C тим самим ланцюжком renotation, що й Lab-апроксимації лабораторії. Решітка
# з кроком 1 ΔE*ab дає мітку вузла; сила сім'ї в точці — частка гаусового ядра (σ — поріг помітності
# разом із похибкою виміру) на вузлах сім'ї, тож на межі сили діляться, а не перемагає порядок рядків. Вузол
# барвної сім'ї віддає ахроматичній частку 1 − ворота тону практиків за його хромою (`ворота_тону`: половина
# при C* 8, межі назви тону ISCC-NBS) — тон згасає з хромою всередині блоку, а не блоком цілим.
# Вузли без даних (поза оболонкою точок renotation чи гамутом sRGB з полем) несуть «невідомо»; частку ядра за
# кінцями шкали світлоти (L* < 0, L* > 100 і вузли, світліші за біле чи темніші за чорне свого стовпця, — кольорів
# там нема) не лічать ні сім'єю, ні «невідомо».
НЕВІДОМО = "невідомо"
_ДАНІ_СІМЕЙ = {}


def _решітка():
    """Розпаковує мітки решітки (байт на вузол, 255 — даних нема, «поза_шкалою» — за кінцем шкали світлоти)
    і звіряє їхній SHA-256."""
    if "мітки" not in _ДАНІ_СІМЕЙ:
        сирі = zlib.decompress(base64.b85decode("".join(_РЕШІТКА_ДАНІ)))
        if hashlib.sha256(сирі).hexdigest() != _РЕШІТКА_СІМЕЙ["sha256"]:
            raise ValueError("решітка сімей не збігається з породженою")
        _ДАНІ_СІМЕЙ["мітки"] = сирі
    return _ДАНІ_СІМЕЙ["мітки"]


def _ядро(σ):
    """Зсуви вузлів у кулі радіуса охоплення·σ навколо цілої точки (кеш за σ з точністю 0.01)."""
    ключ = round(σ, 2)
    if ключ not in _ДАНІ_СІМЕЙ:
        r = int(math.ceil(РЕЄСТР["охоплення_ядра"]["val"] * ключ)) + 1
        _ДАНІ_СІМЕЙ[ключ] = [(dL, da, db) for dL in range(-r, r + 1) for da in range(-r, r + 1)
                             for db in range(-r, r + 1) if dL * dL + da * da + db * db <= r * r]
    return _ДАНІ_СІМЕЙ[ключ]


def сили_сімей(lab, похибка=0.0):
    """Сили сімей точки Lab: {код: частка}, разом з «невідомо» — 1; порожній вхід — {«невідомо»: 1}.

    `похибка` — стандартна похибка виміру кольору в ΔE*ab (розкид значення); σ ядра — її сума
    з порогом помітності, тож сила згасає до межі сім'ї на ширині, якої око й вимір не розрізняють.
    Кінець шкали світлоти — не межа з сусідньою сім'єю: вузли ядра світліші за біле чи темніші за чорне
    (поза L коробки — уся шкала 0–100 — і мітка «поза_шкалою») не лічимо, і сила — частка лише тієї частини
    ядра, що серед можливих кольорів (рішення менеджера 05.11, паспорт `Річ-колір-межі`)."""
    if lab is None or not all(isinstance(x, (int, float)) and math.isfinite(x) for x in lab):
        return {НЕВІДОМО: 1.0}
    σ = math.hypot(РЕЄСТР["поріг_помітності"]["val"], float(похибка or 0.0))
    межа = РЕЄСТР["охоплення_ядра"]["val"] * σ
    мітки, сім_ї, поза = _решітка(), _РЕШІТКА_СІМЕЙ["сім_ї"], _РЕШІТКА_СІМЕЙ["поза_шкалою"]
    (L0, L1), (a0, a1), (b0, b1) = _РЕШІТКА_СІМЕЙ["коробка"]
    na, nb = a1 - a0 + 1, b1 - b0 + 1
    L, a, b = (float(x) for x in lab)
    cL, ca, cb = round(L), round(a), round(b)
    ваги = [0.0] * (len(сім_ї) + 1)
    ахр = сім_ї.index("achromatic")
    c_тону, нахил = РЕЄСТР["ворота_тону"]["val"]
    for dL, da, db in _ядро(σ):
        вL, вa, вb = cL + dL, ca + da, cb + db
        d2 = (вL - L) ** 2 + (вa - a) ** 2 + (вb - b) ** 2
        if d2 > межа * межа:
            continue
        if not L0 <= вL <= L1:
            continue
        мітка = мітки[((вL - L0) * na + (вa - a0)) * nb + (вb - b0)] if a0 <= вa <= a1 and b0 <= вb <= b1 else None
        if мітка == поза:
            continue
        w = math.exp(-d2 / (2 * σ * σ))
        if мітка is None or мітка >= len(сім_ї):
            ваги[-1] += w
            continue
        if мітка != ахр:
            нейтраль = 0.5 - 0.5 * math.tanh(нахил * (math.hypot(вa, вb) - c_тону))
            ваги[ахр] += w * нейтраль
            w *= 1.0 - нейтраль
        ваги[мітка] += w
    разом = sum(ваги)
    if разом <= 0:
        return {НЕВІДОМО: 1.0}
    сили = {к: ваги[і] / разом for і, к in enumerate(сім_ї) if ваги[і] > 0}
    if ваги[-1] > 0:
        сили[НЕВІДОМО] = ваги[-1] / разом
    return dict(sorted(сили.items(), key=lambda п: -п[1]))


def сім_ї_кольору(lab, похибка=0.0):
    """[(код, сила)] — найсильніша сім'я, а коли друга теж значна за тим самим σ, — пара з обома.

    Колір на межі двох сімей належить обом із силою кожної; «невідомо» — лише вимір без даних (сила
    «невідомо» більша за силу кожної сім'ї)."""
    сили = сили_сімей(lab, похибка)
    сім_ї = [(к, с) for к, с in сили.items() if к != НЕВІДОМО]
    if not сім_ї or сили.get(НЕВІДОМО, 0.0) > сім_ї[0][1]:
        return [(НЕВІДОМО, сили.get(НЕВІДОМО, 1.0))]
    if len(сім_ї) > 1 and сім_ї[1][1] >= РЕЄСТР["значна_сила"]["val"]:
        return сім_ї[:2]
    return сім_ї[:1]


def сім_я_кольору(lab, похибка=0.0):
    """(код сім'ї, сила) найсильнішої сім'ї; («невідомо», сила) — лише вимір без даних. Пара — `сім_ї_кольору`."""
    return сім_ї_кольору(lab, похибка)[0]


def _тепло_на_колі(θ):
    """Вісь «жовтіше ↔ синіше» на колі художника: +1 на жовтому полюсі, −1 на синьому, лінійно за дугами."""
    жовтий, синій = РЕЄСТР["полюси_температури"]["val"]
    до_ж = abs((θ - жовтий + 180.0) % 360.0 - 180.0)
    до_с = abs((θ - синій + 180.0) % 360.0 - 180.0)
    return (до_с - до_ж) / (до_с + до_ж)


def температура_сім_ї(lab, похибка=0.0):
    """(код сім'ї, відносна температура) — >0 тепліша (жовтіша) версія сім'ї, <0 холодніша (синіша).

    Барвна сім'я — зсув уздовж осі від центру тону сім'ї; ахроматична — підтон за тією самою віссю;
    хрома в межах σ (тон не визначений) чи сім'я «невідомо» — температура None."""
    код, _ = сім_я_кольору(lab, похибка)
    if код == НЕВІДОМО:
        return код, None
    _, C, h = lch(lab)
    if C <= math.hypot(РЕЄСТР["поріг_помітності"]["val"], float(похибка or 0.0)):
        return код, None
    тепло = _тепло_на_колі(у_коло_художника(h))
    if код == "achromatic":
        return код, тепло
    return код, тепло - _тепло_на_колі(_РЕШІТКА_СІМЕЙ["центри_θ"][код])


